return [
  { json: { codice: "VLV-001", descrizione: "Valvola a sfera DN50", quantita: 4, um: "pz", revisione: "A" } },
  { json: { codice: "FLG-110", descrizione: "Flangia UNI 2278 DN50", quantita: 8, um: "pz", revisione: "A" } },
  { json: { codice: "", descrizione: "Guarnizione spirometallica", quantita: 8, um: "pz", revisione: "A" } },
  { json: { codice: "BLT-M16", descrizione: "Bullone M16x70", quantita: 0, um: "pz", revisione: "B" } },
  { json: { codice: "PIP-002", descrizione: "", quantita: 12, um: "m", revisione: "A" } }
];

const r = { ...$json };
const problemi = [];

if (!r.codice || r.codice.trim() === "") problemi.push("codice mancante");
if (!r.descrizione || r.descrizione.trim().length < 3) problemi.push("descrizione mancante");
if (typeof r.quantita !== "number" || r.quantita <= 0) problemi.push("quantità non valida");
if (!r.um || r.um.trim() === "") problemi.push("unità di misura mancante");
if (!r.revisione || r.revisione.trim() === "") problemi.push("revisione mancante");

r.stato = problemi.length === 0 ? "ok" : "errore";
r.problemi = problemi.join("; ");

return { json: r };

const righe = $input.all().map(i => i.json);
const errori = righe.filter(r => r.stato === "errore");

return {
  json: {
    totale_righe: righe.length,
    righe_ok: righe.length - errori.length,
    righe_errore: errori.length,
    dettaglio_errori: errori.map(r => `${r.codice || "(senza codice)"}: ${r.problemi}`)
  }
};

const r = { ...$json };

r.requestBody = {
  model: "claude-haiku-4-5",
  max_tokens: 200,
  temperature: 0,
  messages: [
    {
      role: "user",
      content: `Sei un classificatore di componenti meccanici e di impianto. Data la descrizione di un articolo di distinta base, restituisci SOLO un JSON con due campi: "categoria" (una tra valvola, flangia, guarnizione, raccordo, tubazione, bulloneria, strumentazione, carpenteria, altro) e "descrizione_norm" (descrizione ripulita, prima lettera maiuscola). Nessun testo prima o dopo il JSON. Descrizione: ${r.descrizione}`
    }
  ]
};

return { json: r };

const originale = $('Valida righe').item.json;

let testo = $json.content[0].text.trim();
testo = testo.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "");

let categoria = "altro";
let descrizione_norm = originale.descrizione;

try {
  const parsed = JSON.parse(testo);
  categoria = parsed.categoria || "altro";
  descrizione_norm = parsed.descrizione_norm || originale.descrizione;
} catch (e) {
  categoria = "errore_parsing";
}

return { json: { ...originale, categoria, descrizione_norm } };$input.item;
